import React, { useEffect, useState } from "react";

function Home() {
  const [articles, setArticles] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/articles/recent/")
      .then((res) => res.json())
      .then((data) => setArticles(data))
      .catch((err) => console.error("Помилка:", err));
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Останні статті (за місяць)</h2>
      {articles.length === 0 ? (
        <p>Немає статей за останній місяць.</p>
      ) : (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {articles.map((a) => (
            <li key={a.id} style={{ marginBottom: "20px" }}>
              <h3>{a.title}</h3>
              <p>{a.excerpt || a.content.substring(0, 120) + "..."}</p>
              <small>
                {a.category} | {new Date(a.created_at).toLocaleDateString()}
              </small>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default Home;
